from typing import List

def find_diagonal_order(nums: List[List[int]]) -> List[int]:
    """
    Finds the diagonal order of a 2D matrix.

    Args:
    nums (List[List[int]]): A 2D matrix of integers.

    Returns:
    List[int]: A list of integers in diagonal order.
    """
    if not nums:
        return []

    m, n = len(nums), len(nums[0])
    diagonals = [[] for _ in range(m + n - 1)]

    for i in range(m):
        for j in range(n):
            index = i + j
            diagonals[index].append(nums[i][j])

    result = []
    for i in range(len(diagonals)):
        if i % 2 == 0:
            result.extend(diagonals[i][::-1])
        else:
            result.extend(diagonals[i])

    return result

# Example usage:
nums = [
    [1, 2, 3],
    [4, 5, 6],
    [7, 8, 9]
]
print(find_diagonal_order(nums))  # Output: [1, 2, 4, 7, 5, 3, 8, 6, 9]
```

