use std::collections::VecDeque;

pub fn find_diagonal_order(nums: Vec<Vec<i32>>) -> Vec<i32> {
    if nums.is_empty() {
        return Vec::new();
    }

    let m = nums.len();
    let n = nums[0].len();
    let mut diagonals = vec![VecDeque::new(); m + n - 1];

    for i in 0..m {
        for j in 0..n {
            let index = i + j;
            diagonals[index].push_back(nums[i][j]);
        }
    }

    let mut result = Vec::new();
    for i in 0..diagonals.len() {
        if i % 2 == 0 {
            for num in diagonals[i].drain(..).rev() {
                result.push(num);
            }
        } else {
            for num in diagonals[i] {
                result.push(num);
            }
        }
    }

    result
}

// Example usage:
fn main() {
    let nums = vec![
        vec![1, 2, 3],
        vec![4, 5, 6],
        vec![7, 8, 9]
    ];
    println!("{:?}", find_diagonal_order(nums));  // Output: [1, 2, 4, 7, 5, 3, 8, 6, 9]
}
```

Both solutions have a time complexity of O(m \* n), where m and n are the number of rows and columns in the input matrix, respectively. The Python solution uses a list comprehension to generate the diagonals, while the Rust solution uses a vector of vectors to store the diagonals.
